"""One record's context: `{(layer_id, signal): float32[n_steps]}` and its provenance.

`values` is what the builder hands to TimeNet. Everything else is the
evidence needed to decide whether it should: which buckets were real, how
much was filled in, and whether any channel came out flat.
"""

entity: EntityKey
anchor: dt.datetime
profile_id: str
values: dict[tuple[str, str], np.ndarray]
present: dict[tuple[str, str], np.ndarray]
imputed_fraction: dict[tuple[str, str], float]
bucket_starts: dict[str, np.ndarray] = field(default_factory=dict)

@property
def service_buckets(self) -> dict[str, np.ndarray]:
    """Per layer, the buckets in which the station saw any traffic at all.

    This is the denominator that makes the imputation gate mean something.
    A 168-hour week contains about 42 overnight hours, and outside the
    largest hubs no train runs in them -- so a quarter of every week is
    empty at *every* grain, on a perfectly healthy record. Measured across
    120 real windows: median imputed fraction 0.20 at station grain, 0.17 at
    line, 0.44 at pair. Judged against a flat 10% budget that rejects 91% of
    station-grain records for the crime of it being three in the morning.

    `station_throughput` is the right denominator because it is a count:
    zero means no train was observed, which is a fact about the timetable
    rather than a gap in the data.
    """
    out: dict[str, np.ndarray] = {}
    for (layer_id, signal), mask in self.present.items():
        if signal == "station_throughput":
            out[layer_id] = mask
    return out

@property
def worst_imputed_fraction(self) -> dict[str, float]:
    """The gate: imputed buckets as a share of buckets that had service.

    Measured over the interpolated channels only. `station_throughput`'s
    gaps are not imputation -- an empty bucket is a counted zero -- so it
    does not vote; it supplies the denominator instead (see
    `service_buckets`).

    Reported per grain, because absence still means different things at
    different grains even after the structural correction: a station with
    no train this hour is a quiet hour, a *service* with no train this hour
    is simply not due.
    """
    service = self.service_buckets
    worst: dict[str, float] = {}
    for (layer_id, signal), fraction in self.imputed_fraction.items():
        spec = SIGNAL_SPECS[signal]
        if spec.impute == "zero":
            continue
        in_service = service.get(layer_id)
        if in_service is not None and in_service.any():
            filled = ~self.present[(layer_id, signal)]
            # Only count a gap where the station was actually running.
            fraction = float(np.count_nonzero(filled & in_service) / np.count_nonzero(in_service))
        worst[spec.grain] = max(worst.get(spec.grain, 0.0), fraction)
    return worst

@property
def overall_imputed_fraction(self) -> float:
    """One number for the whole record: filled buckets over total buckets.

    This is what `build.py`'s `imputed_fraction` annotation describes -- a
    share of the context, not the worst channel. Same interpolated-channel
    denominator as `worst_imputed_fraction`, for the same reason.
    """
    filled = total = 0
    for (layer_id, signal), mask in self.present.items():
        if SIGNAL_SPECS[signal].impute == "zero":
            continue
        filled += int(np.count_nonzero(~mask))
        total += mask.size
    return filled / total if total else 0.0

@property
def within_imputation_budget(self) -> bool:
    return all(
        fraction <= MAX_IMPUTED_FRACTION[grain]
        for grain, fraction in self.worst_imputed_fraction.items()
    )

@property
def degenerate_channels(self) -> tuple[tuple[str, str], ...]:
    return tuple(cell for cell, v in self.values.items() if is_degenerate(v))

def reject_reason(self) -> str | None:
    """Why this window is unusable, or None. The caller's whole decision."""
    if not self.within_imputation_budget:
        over = [
            f"{grain} {fraction:.1%} > {MAX_IMPUTED_FRACTION[grain]:.0%}"
            for grain, fraction in sorted(self.worst_imputed_fraction.items())
            if fraction > MAX_IMPUTED_FRACTION[grain]
        ]
        return "imputed buckets over budget: " + ", ".join(over)
    flat = self.degenerate_channels
    if flat:
        return f"constant channels {sorted(flat)} would z-score to NaN"
    return None

